<script setup lang="ts">
type Shape={id:string;type:string;name:string;x:number;y:number;width:number;height:number;rotation:number;location_ids?:number[];pick_face?:string;target_id?:string;travel_seconds?:number}
type Floor={id:string;name:string;width:number;height:number;objects:Shape[]}
const {t}=useI18n(),route=useRoute(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const record=ref<any>(null),draft=ref<{floors:Floor[]}>({floors:[]}),revision=ref(0),published=ref(0),versions=ref<any[]>([]),version=ref<number|null>(Number(route.query.version)>0?Number(route.query.version):null)
const floorId=ref(''),selectedId=ref(''),loading=ref(true),saving=ref(false),error=ref(''),saved=ref(''),dirty=ref(false),locations=ref<any[]>([]),zoom=ref(1),snap=ref(true),showLabels=ref(true),pointer=ref('—')
const editable=computed(()=>staff.hasPermission('warehouse_edit')&&version.value===null&&!loading.value&&!saving.value)
const floor=computed(()=>draft.value.floors.find(row=>row.id===floorId.value)),selected=computed(()=>floor.value?.objects.find(row=>row.id===selectedId.value))
const persistedDraft=ref('')
const undoStack=ref<string[]>([]),redoStack=ref<string[]>([])
const remember=()=>{const value=JSON.stringify(draft.value);if(undoStack.value.at(-1)!==value){undoStack.value.push(value);if(undoStack.value.length>50)undoStack.value.shift()}redoStack.value=[]}
const canUndo=computed(()=>undoStack.value.some(value=>value!==JSON.stringify(draft.value)))
const undo=()=>{let value=undoStack.value.pop();while(value===JSON.stringify(draft.value))value=undoStack.value.pop();if(!value)return;redoStack.value.push(JSON.stringify(draft.value));draft.value=JSON.parse(value);if(!draft.value.floors.some(f=>f.id===floorId.value))floorId.value=draft.value.floors[0]?.id||'';selectedId.value='';change()}
const redo=()=>{const value=redoStack.value.pop();if(!value)return;undoStack.value.push(JSON.stringify(draft.value));draft.value=JSON.parse(value);if(!draft.value.floors.some(f=>f.id===floorId.value))floorId.value=draft.value.floors[0]?.id||'';selectedId.value='';change()}
const base=computed(()=>'/api/warehouse/warehouse/'+Number(route.params.id))
const kinds=['rack','zone','door','connector','station','wall']
const toolPaths:Record<string,string>={rack:'M4 4h16v16H4z M4 9h16 M4 15h16',zone:'M4 9V4h5 M15 4h5v5 M20 15v5h-5 M9 20H4v-5',door:'M4 21h16 M6 21V4h12v17 M14 12h.01',connector:'M5 3h14v18H5z M12 3v18 M7 10l2-2 2 2 M13 14l2 2 2-2',station:'M3 8h18v5H3z M5 13v8 M19 13v8',wall:'M4 4h16v16H4z M4 9h16 M4 15h16 M9 4v5 M15 9v6 M9 15v5'}
const tickStep=computed(()=>Math.max(1,Math.ceil(Math.max(floor.value?.width||30,floor.value?.height||20)/6)))
const ticks=(length:number)=>Array.from({length:Math.floor(length/tickStep.value)+1},(_,i)=>i*tickStep.value)
const id=()=>crypto.randomUUID()
let generation=0
const apply=(value:any)=>{revision.value=value.revision;published.value=value.published_version;draft.value=value.draft||{floors:[]};floorId.value=draft.value.floors[0]?.id||'';selectedId.value='';persistedDraft.value=JSON.stringify(draft.value);dirty.value=false;undoStack.value=[];redoStack.value=[]}
const load=async()=>{const seq=++generation;loading.value=true;error.value='';const results=await Promise.all([httpRequest<any>(base.value,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),httpRequest<any>(base.value+'/layout',{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),httpRequest<any>(base.value+'/layout/versions')]);if(seq!==generation)return;record.value=results[0];versions.value=results[2]?.items||[];if(results[1])apply(results[1]);loading.value=false}
const change=()=>{dirty.value=JSON.stringify(draft.value)!==persistedDraft.value;saved.value=''}
const addFloor=()=>{if(!editable.value)return;remember();const value:Floor={id:id(),name:t('layout.new-floor',{n:draft.value.floors.length+1}),width:30,height:20,objects:[]};draft.value.floors.push(value);floorId.value=value.id;selectedId.value='';change()}
const removeFloor=async()=>{
 if(!editable.value||!floor.value||draft.value.floors.length<2)return
 const target=floor.value
 if(!await wConfirm({title:t('layout.delete-floor'),message:t('layout.delete-floor-hint',{name:target.name}),confirmText:t('button.delete'),cancelText:t('button.cancel')}))return
 if(!editable.value||!draft.value.floors.includes(target))return
 remember()
 const removed=new Set(target.objects.map(shape=>shape.id))
 draft.value.floors=draft.value.floors.filter(value=>value.id!==target.id)
 for(const value of draft.value.floors)for(const shape of value.objects)if(shape.target_id&&removed.has(shape.target_id)){delete shape.target_id;delete shape.travel_seconds}
 floorId.value=draft.value.floors[0]?.id||'';selectedId.value='';change()
}
const add=(type:string)=>{if(!editable.value||!floor.value)return;remember();const value:Shape={id:id(),type,name:t('layout.kind.'+type)+' '+(floor.value.objects.length+1),x:0,y:0,width:Math.min(type==='rack'?1.2:2,floor.value.width),height:Math.min(type==='rack'?.4:2,floor.value.height),rotation:0};if(type==='rack'){value.location_ids=[];value.pick_face='front'};floor.value.objects.push(value);select(value);change()}
const remove=()=>{if(!editable.value||!selected.value||!floor.value)return;remember();const removed=selected.value.id;floor.value.objects=floor.value.objects.filter(row=>row.id!==removed);for(const f of draft.value.floors)for(const obj of f.objects)if(obj.target_id===removed){delete obj.target_id;delete obj.travel_seconds};selectedId.value='';change()}
const save=async()=>{if(!editable.value||!draft.value.floors.length)return false;saving.value=true;error.value='';const result=await httpRequest<any>(base.value+'/layout',{method:'PUT',body:{revision:revision.value,layout:draft.value},onError:e=>error.value=bizErrorMessage(e)});saving.value=false;if(result){revision.value=result.revision;published.value=result.published_version;persistedDraft.value=JSON.stringify(draft.value);dirty.value=false;saved.value=t('layout.saved');return true}return false}
const publish=async()=>{if(!editable.value)return;if(dirty.value&&!(await save()))return;saving.value=true;error.value='';const result=await httpRequest<any>(base.value+'/layout/publish',{method:'POST',body:{revision:revision.value},onError:e=>error.value=bizErrorMessage(e)});saving.value=false;if(result){revision.value=result.revision;published.value=result.published_version;saved.value=t('layout.published',{n:published.value});const response=await httpRequest<any>(base.value+'/layout/versions');versions.value=response?.items||[]}}
const showVersion=async()=>{if(dirty.value){version.value=null;error.value=t('layout.save-first');return}if(version.value===null){await load();return}loading.value=true;error.value='';const response=await httpRequest<any>(base.value+'/layout/versions/'+version.value,{onError:e=>error.value=bizErrorMessage(e)});if(response){draft.value=response.layout;floorId.value=draft.value.floors[0]?.id||'';selectedId.value=''}loading.value=false}
const connectors=computed(()=>draft.value.floors.flatMap(f=>f.objects.filter(o=>o.type==='connector'&&o.id!==selectedId.value).map(o=>({value:o.id,label:f.name+' · '+o.name}))))
const locationPage=ref(0),locationTotal=ref(0),locationsLoading=ref(false)
const loadLocations=async()=>{if(locationsLoading.value)return;locationsLoading.value=true;const response=await httpRequest<any>('/api/warehouse/location/',{params:{warehouse_id:Number(route.params.id),per_page:100,page:locationPage.value+1},headers:warehouseHeaders(Number(route.params.id)),onError:e=>error.value=bizErrorMessage(e)});locationsLoading.value=false;if(response){locationPage.value++;locationTotal.value=response.total;locations.value.push(...response.items)}}
const select=async(shape:Shape)=>{selectedId.value=shape.id;if(shape.type==='rack'&&staff.hasPermission('location_read')&&!locationPage.value)await loadLocations()}
const bind=(locationId:number,checked:boolean)=>{if(!selected.value)return;remember();const ids=selected.value.location_ids||[];selected.value.location_ids=checked?[...new Set([...ids,locationId])]:ids.filter(value=>value!==locationId);change()}
const boundElsewhere=(locationId:number)=>draft.value.floors.some(f=>f.objects.some(o=>o.id!==selectedId.value&&o.location_ids?.includes(locationId)))
const svg=ref<SVGSVGElement|null>(null)
let drag:{pointer:number;x:number;y:number;ox:number;oy:number;shape:Shape;ow:number;oh:number;corner?:number}|null=null
const point=(event:PointerEvent)=>{const matrix=svg.value?.getScreenCTM();if(!matrix)return null;return new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse())}
const down=(event:PointerEvent,shape:Shape)=>{select(shape);if(!editable.value)return;const pos=point(event);if(!pos)return;remember();drag={pointer:event.pointerId,x:pos.x,y:pos.y,ox:shape.x,oy:shape.y,ow:shape.width,oh:shape.height,shape};svg.value?.setPointerCapture(event.pointerId)}
const resize=(event:PointerEvent,shape:Shape,corner:number)=>{down(event,shape);if(drag)drag.corner=corner}
const move=(event:PointerEvent)=>{const pos=point(event);if(!pos)return;pointer.value=pos.x.toFixed(1)+', '+pos.y.toFixed(1)+' m';if(!drag||!floor.value||!editable.value)return;const round=(value:number)=>Math.round(value/(snap.value?.5:.1))*(snap.value?.5:.1);if(drag.corner!==undefined){const left=drag.corner===0||drag.corner===2,top=drag.corner<2;const dx=round(pos.x-drag.x),dy=round(pos.y-drag.y);const nx=left?Math.max(0,Math.min(drag.ox+drag.ow-.1,drag.ox+dx)):drag.ox,ny=top?Math.max(0,Math.min(drag.oy+drag.oh-.1,drag.oy+dy)):drag.oy;drag.shape.width=left?drag.ox+drag.ow-nx:Math.max(.1,Math.min(floor.value.width-drag.ox,drag.ow+dx));drag.shape.height=top?drag.oy+drag.oh-ny:Math.max(.1,Math.min(floor.value.height-drag.oy,drag.oh+dy));drag.shape.x=nx;drag.shape.y=ny;change();return}drag.shape.x=Math.max(0,Math.min(floor.value.width-drag.shape.width,round(drag.ox+pos.x-drag.x)));drag.shape.y=Math.max(0,Math.min(floor.value.height-drag.shape.height,round(drag.oy+pos.y-drag.y)));change()}
const up=()=>{drag=null}
const keyboard=(event:KeyboardEvent,shape:Shape)=>{if(!editable.value||!floor.value)return;const directions:Record<string,[number,number]>={ArrowLeft:[-.1,0],ArrowRight:[.1,0],ArrowUp:[0,-.1],ArrowDown:[0,.1]};const delta=directions[event.key];if(!delta)return;event.preventDefault();remember();shape.x=Math.max(0,Math.min(floor.value.width-shape.width,Math.round((shape.x+delta[0])*10)/10));shape.y=Math.max(0,Math.min(floor.value.height-shape.height,Math.round((shape.y+delta[1])*10)/10));change()}
const rotate=(angle:number)=>{if(!selected.value||!floor.value)return;remember();const s=selected.value;if(Math.abs(s.rotation-angle)%180!==0)[s.width,s.height]=[s.height,s.width];s.rotation=angle;change()}
const leave=(event:BeforeUnloadEvent)=>{if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>{if(dirty.value){error.value=t('layout.save-first');return false}})
onMounted(async()=>{await load();if(Number(route.query.version)>0){version.value=Number(route.query.version);await showVersion()}if(draft.value.floors.some(f=>f.id===route.query.floor))floorId.value=String(route.query.floor);window.addEventListener('beforeunload',leave)})
onBeforeUnmount(()=>{generation++;window.removeEventListener('beforeunload',leave)})
useHead({title:()=>t('layout.title')})
</script>
<template><div class="w-layout-editor w-scope"><nav><NuxtLink class="w-layout-back" :to="'/warehouse/detail/'+route.params.id">{{record?.name||t('nav.warehouse')}}</NuxtLink><span>/</span>{{t('layout.title')}}</nav><header><div><h1>{{record?.name}} {{t('layout.title')}}<template v-if="floor"> · {{floor.name}}</template></h1><p>{{t('layout.revision',{n:revision})}} · {{t('layout.published',{n:published})}}<span v-if="dirty"> · {{t('layout.unsaved')}}</span></p></div><div class="actions"><WButton v-if="editable" :disabled="!canUndo" @click="undo">{{t('layout.undo')}}</WButton><WButton v-if="editable" :disabled="!redoStack.length" @click="redo">{{t('layout.redo')}}</WButton><WSelect v-model="version" :placeholder="t('layout.draft')" allow-empty :options="versions.map(row=>({value:row.version,label:t('layout.version',{n:row.version})}))" :disabled="saving||loading" @update:model-value="showVersion"/><WButton v-if="dirty" :disabled="saving||loading" @click="load">{{t('layout.discard')}}</WButton><WButton v-if="staff.hasPermission('warehouse_edit')" :disabled="!editable||!dirty" :loading="saving" @click="save">{{t('button.save')}}</WButton><WButton v-if="staff.hasPermission('warehouse_edit')" variant="primary" :disabled="!editable||!draft.floors.length" @click="publish">{{t('layout.publish')}}</WButton></div></header>
<WAlert v-if="error" tone="block" :title="error"/><p v-if="saved" role="status" class="saved">{{saved}}</p><WEmptyState v-if="loading" :title="t('common.status.loading')"/>
<div v-else class="editor"><aside class="floors"><button v-for="f in draft.floors" :key="f.id" class="floor-button" :class="{'is-active':f.id===floorId}" @click="floorId=f.id;selectedId=''">{{f.name}}<small>{{f.objects.length}} {{t('layout.objects')}}</small></button><WButton v-if="editable" @click="addFloor">{{t('layout.add-floor')}}</WButton></aside><aside class="tool-rail"><template v-if="editable"><button v-for="kind in kinds" :key="kind" type="button" :disabled="!floor" @click="add(kind)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path :d="toolPaths[kind]"/></svg><span>{{t('layout.kind.'+kind)}}</span></button></template></aside><section class="drawing"><div class="tools"><WSelect v-model="zoom" :options="[.5,1,1.5,2].map(value=>({value,label:value*100+'%'}))"/><label><input v-model="snap" type="checkbox"/>{{t('layout.snap')}}</label><label><input v-model="showLabels" type="checkbox"/>{{t('layout.show-labels')}}</label><small class="pointer">{{pointer}}</small></div><WEmptyState v-if="!floor" :title="t('layout.no-floor')"/><div v-else class="canvas"><svg ref="svg" :viewBox="`-1 -1 ${floor.width+2} ${floor.height+2}`" :style="{width:zoom*100+'%',minWidth:560*zoom+'px'}" role="img" :aria-label="floor.name" @pointermove="move" @pointerup="up" @pointercancel="up" @pointerdown="event=>{if(!(event.target as Element).closest('g.shape'))selectedId=''}"><defs><pattern id="floor-grid" width=".5" height=".5" patternUnits="userSpaceOnUse"><path d="M .5 0 L 0 0 0 .5" fill="none" stroke="#EDEFF3" stroke-width=".015"/></pattern></defs><rect x="0" y="0" :width="floor.width" :height="floor.height" fill="white" stroke="#CDD1DA" stroke-width=".04"/><rect x="0" y="0" :width="floor.width" :height="floor.height" fill="url(#floor-grid)"/><g class="ruler"><text v-for="tick in ticks(floor.width)" :key="'x'+tick" :x="tick" y="-.35" font-size=".25" text-anchor="middle">{{tick}}</text><text v-for="tick in ticks(floor.height)" :key="'y'+tick" x="-.25" :y="tick" font-size=".25" text-anchor="end">{{tick}}</text></g><g v-for="shape in floor.objects" :key="shape.id" tabindex="0" role="button" :aria-label="shape.name" :class="['shape',shape.type,{'is-selected':shape.id===selectedId}]" @pointerdown.stop="down($event,shape)" @keydown="keyboard($event,shape)" @focus="select(shape)"><rect :x="shape.x" :y="shape.y" :width="shape.width" :height="shape.height" stroke-width=".05"/><text v-if="showLabels" :x="shape.x+shape.width/2" :y="shape.y+shape.height/2" font-size=".28" text-anchor="middle" dominant-baseline="middle">{{shape.name}}</text><template v-if="shape.id===selectedId"><rect v-for="(corner,index) in [[shape.x,shape.y],[shape.x+shape.width,shape.y],[shape.x,shape.y+shape.height],[shape.x+shape.width,shape.y+shape.height]]" :key="corner.join(',')" :x="corner[0]!-.07" :y="corner[1]!-.07" width=".14" height=".14" fill="white" style="cursor:nwse-resize" @pointerdown.stop="resize($event,shape,index)"/></template></g></svg></div><footer>{{t('layout.units')}}<template v-if="floor"> · {{floor.width}} × {{floor.height}} m</template></footer></section><aside class="properties"><div class="property-heading"><small>{{selected?t('layout.kind.'+selected.type):t('layout.floor-settings')}}</small><h2>{{selected?.name||floor?.name}}</h2></div><fieldset :disabled="!editable" @focusin="remember" @input="change" @change="change"><template v-if="selected"><WField :label="t('common.fields.name')"><WInput v-model="selected.name" maxlength="80"/></WField><div class="property-grid"><WField v-for="key in ['x','y','width','height'] as const" :key="key" :label="t('layout.'+key)"><WInput v-model.number="selected[key]" type="number" step="0.1" min="0" suffix="m"/></WField></div><WField :label="t('layout.rotate')"><div class="segments" role="group" :aria-label="t('layout.rotate')"><button v-for="angle in [0,90,180,270]" :key="angle" type="button" :class="{active:selected.rotation===angle}" :aria-pressed="selected.rotation===angle" @click="rotate(angle)">{{angle}}°</button></div></WField><template v-if="selected.type==='rack'"><WField :label="t('layout.pick-face')"><div class="segments" role="group" :aria-label="t('layout.pick-face')"><button v-for="face in ['front','back','both']" :key="face" type="button" :class="{active:selected.pick_face===face}" :aria-pressed="selected.pick_face===face" @click="remember();selected.pick_face=face;change()">{{t('layout.'+face)}}</button></div></WField><h3>{{t('nav.location')}}</h3><div class="bindings"><label v-for="location in locations" :key="location.id"><input type="checkbox" :checked="selected.location_ids?.includes(location.id)" :disabled="boundElsewhere(location.id)||!editable" @change="bind(location.id,($event.target as HTMLInputElement).checked)"/>{{location.code}}</label></div><WButton v-if="locations.length<locationTotal" size="sm" :loading="locationsLoading" @click="loadLocations">{{t('layout.load-more')}}</WButton></template><template v-if="selected.type==='connector'"><WField :label="t('layout.target')"><WSelect v-model="selected.target_id" :options="connectors" :placeholder="t('layout.select-target')"/></WField><WField :label="t('layout.travel-seconds')"><WInput v-model.number="selected.travel_seconds" type="number" min="0" max="86400"/></WField></template><WButton variant="text" @click="remove">{{t('button.delete')}}</WButton></template><template v-else-if="floor"><WField :label="t('common.fields.name')"><WInput v-model="floor.name" maxlength="80"/></WField><WField v-for="key in ['width','height'] as const" :key="key" :label="t('layout.'+key)"><WInput v-model.number="floor[key]" type="number" min="1" max="2000" suffix="m"/></WField><WButton v-if="editable" variant="danger" :disabled="draft.floors.length<2" @click="removeFloor">{{t('layout.delete-floor')}}</WButton></template></fieldset></aside></div></div></template>
<style scoped>
.w-layout-editor{display:flex;flex-direction:column;gap:16px}nav{display:flex;gap:8px;font-size:12px;color:var(--w-text-3)}.w-layout-back{color:inherit;text-decoration:none}header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:24px;line-height:32px;font-weight:600;margin:0}header p{margin:4px 0 0;font-size:12px;line-height:18px;color:var(--w-text-3)}.actions{display:flex;gap:8px;flex-wrap:wrap}.editor{display:grid;grid-template-columns:180px minmax(0,1fr) 260px;border:1px solid var(--w-border);border-radius:10px;overflow:hidden;background:white;min-height:620px}aside{padding:16px;min-width:0}h2{margin:0 0 16px;font-size:14px;line-height:20px;font-weight:600}h3{font-size:13px;line-height:20px;font-weight:600;margin:8px 0 0}.floors{border-right:1px solid var(--w-line);display:flex;flex-direction:column;gap:8px}.floor-button{background:transparent;border:0;border-radius:6px;padding:10px;text-align:left;font:inherit;font-size:13px;line-height:20px;cursor:pointer}.floor-button.is-active{background:#F1EBFF;color:#5F1FE6}small{display:block;font-size:12px;color:var(--w-text-3)}.drawing{min-width:0;display:flex;flex-direction:column}.tools{display:flex;flex-wrap:wrap;gap:6px;padding:12px;border-bottom:1px solid var(--w-line)}.tools>.w-select{width:80px;margin-left:auto}.canvas{background:#F6F7FA;overflow:auto;flex:1;max-height:650px;min-height:400px}.canvas svg{display:block;height:auto;touch-action:none}.shape{cursor:move;outline:none}.shape rect{fill:white;stroke:#4C5261}.shape.wall rect{fill:#656C7A}.shape.zone rect{fill:#F6F7FA;stroke-dasharray:.2 .15}.shape.connector rect{fill:#EEE8FF;stroke:#8877CC}.shape.station rect{fill:#EDEFF3}.shape.door rect{fill:#E9F4EC;stroke-dasharray:.2 .15}.shape.is-selected rect,.shape:focus rect{stroke:#5F1FE6;stroke-width:.1}.shape text{fill:#151923;pointer-events:none;user-select:none}footer{border-top:1px solid var(--w-line);padding:10px 16px;font-size:12px;color:var(--w-text-3)}.properties{border-left:1px solid var(--w-line)}fieldset{border:0;padding:0;margin:0;display:flex;flex-direction:column;gap:12px;min-width:0}.property-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bindings{max-height:200px;overflow:auto;display:flex;flex-direction:column;gap:8px;font-size:13px}.bindings label{display:flex;gap:8px;align-items:center}.bindings input{accent-color:#5F1FE6}.saved{font-size:13px;margin:0;color:#247B3F}@media(max-width:1100px){.editor{grid-template-columns:150px minmax(0,1fr)}.properties{grid-column:1/-1;border-left:0;border-top:1px solid var(--w-line)}}@media(max-width:600px){.editor{grid-template-columns:minmax(0,1fr)}.floors{border-right:0;border-bottom:1px solid var(--w-line)}.canvas{min-height:320px}.actions{width:100%}}

/* Match the recovered editor: floor tabs above, narrow tool rail, separate inspector. */
